size_t need = base64_encoded_len(raw_len);
bool add_nul = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0; // sometimes provision extra byte for a NUL terminator
size_t out_cap = need + (add_nul ? 1u : 0u);
