size_t produced = base64_encode(static_cast<const void *>(raw_buf.data()), raw_len, const_cast<char *>(out.data()), out_cap);
// Property: the encoder must not write more than the provided capacity
FUZZ_ASSERT(produced <= out_cap, "base64_encode wrote more than provided capacity");
